<?php $permissions=(array)($data['user']['permissions']??[]);$can=static fn(string $p):bool=>in_array($p,$permissions,true);$transfer=$data['transfer']??null;$status=static fn(string $s):string=>'badge '.(in_array($s,['done'],true)?'badge-success':(in_array($s,['submitted','approved','in_transit'],true)?'badge-warning':'badge-neutral'));?>
<div class="module-stack"><div class="page-actions"><a class="btn btn-secondary" href="<?=e(appBasePath())?>/inventory">Stock</a><a class="btn btn-secondary" href="<?=e(appBasePath())?>/inventory?section=movements">Movement history</a></div>
<?php if(!empty($data['notice'])):?><div class="alert alert-success"><?=e($data['notice'])?></div><?php endif;?><?php if(!empty($data['error'])):?><div class="alert alert-danger"><?=e($data['error'])?></div><?php endif;?>
<?php if(is_array($transfer)):?><section class="card"><div class="section-heading"><div><small>Internal transfer</small><h2><?=e($transfer['transfer_number'])?></h2></div><span class="<?=$status($transfer['status'])?>"><?=e(str_replace('_',' ',$transfer['status']))?></span></div><p><strong>Source:</strong> <?=e($transfer['source_warehouse_name'].' / '.$transfer['source_location_name'])?> → <strong>Destination:</strong> <?=e($transfer['destination_warehouse_name'].' / '.$transfer['destination_location_name'])?></p><p><strong>Reason:</strong> <?=e($transfer['reason']??$transfer['notes']??'—')?></p><table class="data-table"><thead><tr><th>Product</th><th>Requested</th><th>Dispatched</th><th>Received</th><th>On hand</th><th>Reserved</th><th>Available</th></tr></thead><tbody><?php foreach($transfer['lines'] as $line):?><tr><td><?=e($line['sku'].' — '.$line['product_name'])?></td><td><?=e($line['quantity'])?></td><td><?=e($line['dispatched_quantity'])?></td><td><?=e($line['received_quantity'])?></td><td><?=e($line['quantity_on_hand']??0)?></td><td><?=e($line['quantity_reserved']??0)?></td><td><?=e($line['quantity_available']??0)?></td></tr><?php endforeach;?></tbody></table><div class="page-actions"><?php if($transfer['status']==='draft'&&$can('inventory.transfers.create')):?><form method="post" action="<?=e(appBasePath())?>/inventory/transfers/<?=$transfer['transfer_id']?>/action"><?=csrfField()?><button class="btn btn-primary" name="action" value="submit">Submit</button><button class="btn btn-secondary" name="action" value="cancel">Cancel</button></form><?php elseif($transfer['status']==='submitted'&&$can('inventory.transfers.approve')):?><form method="post" action="<?=e(appBasePath())?>/inventory/transfers/<?=$transfer['transfer_id']?>/action"><?=csrfField()?><button class="btn btn-primary" name="action" value="approve">Approve transfer</button></form><?php elseif($transfer['status']==='approved'&&$can('inventory.transfers.dispatch')):?><form method="post" action="<?=e(appBasePath())?>/inventory/transfers/<?=$transfer['transfer_id']?>/dispatch"><?=csrfField()?><button class="btn btn-primary">Dispatch transfer</button></form><?php elseif($transfer['status']==='in_transit'&&$can('inventory.transfers.receive')):?><form method="post" action="<?=e(appBasePath())?>/inventory/transfers/<?=$transfer['transfer_id']?>/receive"><?=csrfField()?><button class="btn btn-primary">Receive transfer</button></form><?php endif;?></div></section><?php endif;?>
<?php if($can('inventory.transfers.create')&&!is_array($transfer)):?><section class="card"><h2>Create internal transfer</h2><form method="post" action="<?=e(appBasePath())?>/inventory/transfers"><?=csrfField()?><div class="enterprise-form"><label>Source Warehouse<select name="source_warehouse_id" required><option value="">Select</option><?php foreach($data['warehouses'] as $w):?><option value="<?=$w['warehouse_id']?>"><?=e($w['code'].' — '.$w['name'])?></option><?php endforeach;?></select></label><label>Source Location<select name="source_location_id" required><option value="">Select</option><?php foreach($data['locations'] as $l):?><option value="<?=$l['location_id']?>" data-warehouse="<?=$l['warehouse_id']?>"><?=e($l['code'].' — '.$l['name'])?></option><?php endforeach;?></select></label><label>Destination Warehouse<select name="destination_warehouse_id" required><option value="">Select</option><?php foreach($data['warehouses'] as $w):?><option value="<?=$w['warehouse_id']?>"><?=e($w['code'].' — '.$w['name'])?></option><?php endforeach;?></select></label><label>Destination Location<select name="destination_location_id" required><option value="">Select</option><?php foreach($data['locations'] as $l):?><option value="<?=$l['location_id']?>" data-warehouse="<?=$l['warehouse_id']?>"><?=e($l['code'].' — '.$l['name'])?></option><?php endforeach;?></select></label><label>Product<select name="product_id[]" required><option value="">Select</option><?php foreach($data['products'] as $p):?><option value="<?=$p['product_id']?>"><?=e($p['sku'].' — '.$p['name'])?></option><?php endforeach;?></select></label><label>Quantity<input name="quantity[]" type="number" min="0.001" step="0.001" required></label><label>Transfer reason<textarea name="reason" required maxlength="500"></textarea></label><label>Reference / note<textarea name="notes" maxlength="500"></textarea></label></div><button class="btn btn-primary">Create draft</button></form></section><?php endif;?>
<section class="card table-card"><h2>Transfers</h2><table class="data-table"><thead><tr><th>Transfer</th><th>Source</th><th>Destination</th><th>Product / Qty</th><th>Dispatched</th><th>Received</th><th>Status</th><th>Action required</th></tr></thead><tbody><?php foreach($data['transfers'] as $row):?><tr><td><a href="<?=e(appBasePath())?>/inventory/transfers/<?=$row['transfer_id']?>"><?=e($row['transfer_number'])?></a></td><td><?=e($row['source_warehouse_name'].' / '.$row['source_location_name'])?></td><td><?=e($row['destination_warehouse_name'].' / '.$row['destination_location_name'])?></td><td><?=e($row['product_summary'])?></td><td><?=e($row['dispatched_quantity'])?></td><td><?=e($row['received_quantity'])?></td><td><span class="<?=$status($row['status'])?>"><?=e(str_replace('_',' ',$row['status']))?></span></td><td><?=e($row['status']==='submitted'?'Approve transfer':($row['status']==='approved'?'Dispatch transfer':($row['status']==='in_transit'?'Receive transfer':'—')))?></td></tr><?php endforeach;?></tbody></table></section></div>
<script>document.querySelectorAll('select[name$="_warehouse_id"]').forEach(function(w){var target=w.name.indexOf('source_')===0?'source_location_id':'destination_location_id',l=document.querySelector('select[name="'+target+'"]');var filter=function(){Array.from(l.options).forEach(function(o,i){if(i)o.hidden=o.dataset.warehouse!==w.value;});if(l.selectedOptions[0]&&l.selectedOptions[0].hidden)l.value='';};w.addEventListener('change',filter);filter();});</script>
